arguments.command:
cd /src/php-src && pid=$(cat /tmp/make2.pid 2>/dev/null || echo '')
if [ -n "$pid" ]; then
  echo "Waiting for make pid=$pid";
  while kill -0 "$pid" 2>/dev/null; do
    echo "...still building (pid=$pid, $(date -u +%H:%M:%S))";
    sleep 10;
  done
  echo "make finished";
  wait "$pid" 2>/dev/null || true;
  echo "rc=$?";
fi
# show last output
if [ -f /tmp/make2.log ]; then tail -n 60 /tmp/make2.log; fi
# verify php binary exists
ls -la sapi/cli/php 2>/dev/null && echo 'php exists'

